public Change(String drink, int units, String reason) {
            this.drink = drink;
            this.units = units;
            this.reason = reason;
        }

public Line(String drink, int quantity, int price) {
            this.drink = drink;
            this.quantity = quantity;
            this.price = price;
        }

public Order(String customer, List<Line> lines, Map<String, String> notes) {
        this.customer = customer;
        this.lines = List.copyOf(lines);
        this.notes = Map.copyOf(notes);
    }

public OrderService(Inventory inventory, Brewer brewer) {
        this.inventory = inventory;
        this.brewer = brewer;
    }

public OrderService(Inventory inventory) {
        this(inventory, new Brewer());
    }
